messages.content:
Tool response:
Tool: add_patient_insurance_policy
Description: Add a new insurance policy for a patient.
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "description": "Internal ID of the patient",
          "title": "Patient Id"
        },
        "provider_id": {
          "type": "integer",
          "title": "Provider Id"
        },
        "policy_number": {
          "type": "string",
          "title": "Policy Number"
        },
        "is_primary": {
          "type": "boolean",
          "title": "Is Primary",
          "default": false
        }
      },
      "required": [
        "patient_id",
        "provider_id",
        "policy_number"
      ]
    }
